[CmdletBinding(SupportsShouldProcess)]param()
$ErrorActionPreference='Stop';$startup=[Environment]::GetFolderPath('Startup');$shortcut=Join-Path $startup 'NEEWA Hermes Desktop.lnk';if($PSCmdlet.ShouldProcess($shortcut,'Remove startup shortcut')){Remove-Item -Force $shortcut -ErrorAction SilentlyContinue};$home=if($env:HERMES_HOME){$env:HERMES_HOME}else{Join-Path $env:LOCALAPPDATA 'hermes'};foreach($path in @((Join-Path $home 'desktop-plugins\neewa-command-center'),(Join-Path $home 'skins\neewa.yaml'))){if($PSCmdlet.ShouldProcess($path,'Remove NEEWA asset')){Remove-Item -Recurse -Force $path -ErrorAction SilentlyContinue}};Write-Host 'NEEWA assets removed. Hermes data, credentials, sessions, and Tailscale preserved.'
